/** Writes firmware/test/vectors.h: what the device has to produce, generated by the implementation the chain accepts. */
import { writeFileSync } from "node:fs";
import { type Address, type Hex, bytesToHex, encodeFunctionData, keccak256, numberToHex, toBytes } from "viem";
import { accountAbi, encodeTx, leafNonceKey, masterDigest, masterTx, sigHash, type Call, type FrameTx } from "../src/frame.ts";
import { ops } from "../src/account.ts";
import { KeyTree, WOTS_W16, encodeMasterSignature, keccak, wotsSign } from "../src/wots.ts";

const text = (s: string) => new TextEncoder().encode(s);
const u32 = (n: number) => toBytes(numberToHex(n, { size: 4 }));

const master = keccak(text("vajra device test vector"));
const seedOf = (tree: number) => keccak(master, text("vajra-tree"), u32(tree));
const tree = KeyTree.fromSeed(WOTS_W16, seedOf(0));
const nextTree = KeyTree.fromSeed(WOTS_W16, seedOf(1));
const root = bytesToHex(tree.root);
const nextRoot = bytesToHex(nextTree.root);
const account = "0x1111111111111111111111111111111111111111" as Address;
const other = "0x2222222222222222222222222222222222222222" as Address;
const epochSalt = keccak256(text("epoch"));
const chainId = 1337;

const raw = (tx: FrameTx) => encodeTx(tx).slice(2);
const at = (leaf: number, call: Call) => masterTx({ account, root, leaf, calls: [call] });

function signed(tx: FrameTx, leaf: number) {
  const digest = masterDigest({ chainId, epochSalt, account, nonceKey: leafNonceKey(root, leaf), sigHash: sigHash(tx) });
  const blob = encodeMasterSignature(leaf, wotsSign(WOTS_W16, seedOf(0), leaf, toBytes(digest)), tree.path(leaf));
  return { digest, blob: bytesToHex(blob).slice(2) };
}

const freeze = at(0, ops.freeze());
const first = signed(freeze, 0);
const veto = at(1, ops.veto(7n));
const second = signed(veto, 1);

const values: Record<string, string> = {
  MASTER: bytesToHex(master).slice(2),
  ROOT: root.slice(2),
  NEXT_ROOT: nextRoot.slice(2),
  ACCOUNT: account.slice(2),
  EPOCH: epochSalt.slice(2),
  TX_FREEZE: raw(freeze),
  SIGHASH_FREEZE: sigHash(freeze).slice(2),
  DIGEST_FREEZE: first.digest.slice(2),
  BLOB_FREEZE: first.blob,
  TX_VETO_LEAF1: raw(veto),
  BLOB_VETO_LEAF1: second.blob,
  TX_UNFREEZE_LEAF0: raw(at(0, ops.unfreeze())),
  TX_LEAF2: raw(at(2, ops.freeze())),
  TX_ESCAPE_LEAF1: raw(at(1, ops.escape(other, keccak256(text("salt"))))),
  TX_ESCAPE_EXTRA_LEAF1: raw(at(1, ops.escape(other, keccak256(text("salt")), [other, account]))),
  TX_DAILY_KEY_LEAF1: raw(at(1, ops.setDailyKey(other))),
  TX_RULE_LEAF1: raw(at(1, ops.setRule("0x0000000000000000000000000000000000000000", 5n, 6n))),
  TX_ROTATE_LEAF1: raw(at(1, ops.rotateRoot(nextRoot))),
  TX_ROTATE_WRONG_ROOT_LEAF1: raw(at(1, ops.rotateRoot(keccak256(text("attacker tree"))))),
  TX_FREEZE_ROTATION_LEAF: raw(at(63, ops.freeze())),
  TX_ROTATE_ROTATION_LEAF: raw(at(63, ops.rotateRoot(nextRoot))),
  TX_WRONG_ACCOUNT: raw({ ...freeze, sender: other }),
  TX_WRONG_CHAIN: raw({ ...freeze, chainId: 1n }),
  TX_UNKNOWN_OP: raw(at(0, { data: "0xdeadbeef", execution: 60_000n, state: 100_000n })),
  TX_TRAILING_DATA: raw(at(0, { data: `${ops.freeze().data}00`, execution: 60_000n, state: 100_000n })),
  TX_EXTERNAL_TARGET: raw(at(0, { target: other, data: ops.freeze().data, execution: 60_000n, state: 100_000n })),
  TX_WITH_VALUE: raw(at(0, { ...ops.freeze(), value: 1n })),
  TX_HIGH_FEE: raw(masterTx({ account, root, leaf: 0, calls: [ops.freeze()], fees: { maxFeePerGas: 100_000_000_000_000n } })),
  TX_NEXT_SEQUENCE: raw({ ...freeze, nonceSeq: 1n }),
  TX_FOREIGN_TREE: raw(masterTx({ account, root: nextRoot, leaf: 0, calls: [ops.freeze()] })),
  TX_DAILY_VERIFY: raw({
    ...freeze,
    frames: [{ ...freeze.frames[0]!, data: encodeFunctionData({ abi: accountAbi, functionName: "validateDaily", args: [3] }) }, freeze.frames[1]!],
  }),
  TX_THREE_FRAMES: raw({ ...freeze, frames: [freeze.frames[0]!, freeze.frames[1]!, freeze.frames[1]!] }),
  TX_SIGNED_ENTRY: raw({ ...freeze, signatures: [{ ...freeze.signatures[0]!, signature: "0x01" as Hex }] }),
};

const header = [
  "// Generated by packages/core/scripts/gen-device-vectors.ts. Do not edit.",
  "#pragma once",
  "",
  ...Object.entries(values).map(([name, value]) => `static const char* const V_${name} = "${value}";`),
  "",
].join("\n");
writeFileSync(new URL("../../../firmware/test/vectors.h", import.meta.url), header);
console.log(`${Object.keys(values).length} vectors`);
